// Logos do PDF do cronograma do aluno, embutidos em base64. ARQUIVO GERADO: não edite à mão.
//
// Por que base64 dentro de um .ts, e não o PNG ao lado:
//   - a edge não tem o pipeline de assets do Vite (o front importa o PNG e recebe uma URL);
//   - ler arquivo irmão com Deno.readFile no edge-runtime self-hosted não é garantido (o deploy
//     copia a pasta para dentro do container e o caminho muda);
//   - o import de módulo sempre funciona, e o PNG vai junto no mesmo deploy da função.
//
// Por que 480 px no PPGVET: o PNG original (src/assets/ppgvet-logo-pdf.png) tem 1920x1080 RGBA
// e o PDF do navegador o grava sem compressão: sozinho ele dá ~8 MB de PDF. Impresso com 56 pt
// de altura, 480 px ainda são ~350 dpi. O PPG Educação (src/assets/logo-ppg-educacao.png) já é
// pequeno (909x310, 21 KB) e vai inteiro.
//
// Como regerar (se a marca mudar o logo):
//   sips -Z 480 src/assets/ppgvet-logo-pdf.png --out /tmp/ppgvet-480.png
//   base64 -i /tmp/ppgvet-480.png          → ppgvet.dataUrl (largura 480, altura 270)
//   base64 -i src/assets/logo-ppg-educacao.png → ppg.dataUrl (largura 909, altura 310)

/** Valores de `ped_pos_graduacoes.marca` (CHECK no banco: 'ppgvet' | 'ppg'). */
export type Marca = "ppgvet" | "ppg";

export interface LogoPdf {
  /** PNG em data URL, pronto para o `doc.addImage`. */
  dataUrl: string;
  /** Pixels do PNG: a proporção do desenho sai daqui, nunca de um 16:9 fixo. */
  largura: number;
  altura: number;
  /**
   * Altura impressa, em pt. O cabeçalho reserva uma caixa de 56 pt (a altura do logo PPGVET
   * de sempre) e o logo é centralizado nela. O PPG Educação é uma marca horizontal sem margem
   * transparente: com os mesmos 56 pt ele sairia com 164 pt de largura e pesaria o dobro do
   * PPGVET, por isso sai com 38 pt (cerca de 111 pt de largura, a mesma área visível).
   */
  alturaPt: number;
}

export const LOGOS: Record<Marca, LogoPdf> = {
  ppgvet: {
    largura: 480,
    altura: 270,
    alturaPt: 56,
    dataUrl: "data:image/png;base64,",
  },
  ppg: {
    largura: 909,
    altura: 310,
    alturaPt: 38,
    dataUrl: "data:image/png;base64,",
  },
};
